def link(section): return '/admin/' + section + '.html'
def badge(text, tone='neutral'): return f'<span class="status status-{tone}">{escape(text)}</span>'
def sample_notice(): return '<div class="admin-sample"><span class="sample-dot"></span>Design preview · sample content and figures · changes are not saved</div>'
def field(label, value='', typ='text', hint=''):
    return f'<label class="admin-field"><span>{escape(label)}</span><input type="{typ}" value="{escape(value, quote=True)}" placeholder="{escape(hint, quote=True)}"></label>'
def button(label, cls='secondary', action='demo'): return f'<button class="a-button {cls}" type="button" data-admin-action="{action}">{label}</button>'

def shell(section, content):
    name,desc=DESCRIPTIONS[section]
    groups=''.join(f'<div class="side-group"><div class="side-group-label">{label}</div>'+''.join(f'<a class="side-link {"active" if key==section else ""}" href="{link(key)}" {"aria-current=page" if key==section else ""}><span class="side-icon">{icon(icon_name)}</span><span>{title}</span></a>' for key,title,icon_name in items)+'</div>' for label,items in NAV)
    return f'''<div class="studio">
      <aside class="studio-sidebar"><a class="studio-brand" href="/"><img src="/assets/logo-white.svg" alt="FinancersHub" width="184" height="34"><span>EDITORIAL STUDIO</span></a><nav aria-label="Editorial studio">{groups}</nav><div class="side-bottom"><div class="user-dot">FH</div><div><strong>Editorial team</strong><small>Workspace preview</small></div><span aria-hidden="true">⋯</span></div></aside>
      <div class="studio-workspace"><header class="studio-topbar"><button class="mobile-studio-menu" id="studio-menu" type="button" aria-label="Open studio menu" aria-expanded="false">☰</button><div class="studio-crumb">FinancersHub <span>/</span> Editorial studio <span>/</span> {name}</div><div class="topbar-actions"><button class="studio-theme" id="studio-theme" type="button" aria-label="Toggle studio dark mode">◐</button><a href="/" target="_blank" rel="noopener">View site ↗</a><a class="topbar-create" href="/admin/editor.html">＋ New article</a><span class="topbar-avatar" aria-label="Editorial team">FH</span></div></header>
      <main id="main" class="studio-main">{sample_notice()}<div class="studio-heading"><div><span class="admin-kicker">EDITORIAL STUDIO / {section.upper()}</span><h1>{name}</h1><p>{desc}</p></div></div>{content}</main></div></div>'''

