def article_list(articles):
    states=[('Published','green'),('Draft','blue'),('In review','amber'),('Scheduled','purple')]
    rows=''.join(f'<tr data-row-status="{states[i%4][0].lower().replace(" ","-")}" data-row-search="{escape((a[0]+" "+a[1]).lower(),quote=True)}"><td><label class="check"><input type="checkbox" aria-label="Select {escape(a[0],quote=True)}"></label></td><td><a class="story-title" href="/admin/editor.html">{escape(a[0])}</a><small>/articles/{a[4]}</small></td><td>{a[1]}</td><td>{badge(*states[i%4])}</td><td class="muted">Editorial team</td><td class="muted">Sep {24-i}, 2026</td><td><a class="row-action" href="/admin/editor.html" aria-label="Edit {escape(a[0],quote=True)}">Edit ↗</a></td></tr>' for i,a in enumerate(articles))
    return f'''<div class="list-toolbar"><div class="segmented" role="group" aria-label="Filter articles">{''.join(f'<button type="button" class="{"selected" if k=="all" else ""}" data-status-filter="{k}">{t}</button>' for k,t in [('all','All articles'),('published','Published'),('draft','Drafts'),('in-review','In review'),('scheduled','Scheduled')])}</div><a class="a-button primary" href="/admin/editor.html">＋ New article</a></div><section class="studio-panel list-panel"><div class="table-controls"><label class="table-search">⌕ <input id="admin-search" type="search" placeholder="Search titles or categories" aria-label="Search articles"></label><div><select aria-label="Category filter"><option>All categories</option>{''.join(f'<option>{x}</option>' for x in ['Personal Finance','Investing','Banking','Credit','Business'])}</select>{button('Filters ▾')}</div></div><div class="table-scroll"><table class="studio-table"><thead><tr><th><input type="checkbox" aria-label="Select all visible articles" id="select-all"></th><th>Article</th><th>Category</th><th>Status</th><th>Author</th><th>Last updated</th><th></th></tr></thead><tbody>{rows}</tbody></table></div><div class="table-footer"><span id="article-count">Showing 11 sample articles</span><span>1 of 1 pages</span></div></section>'''

def editor():
    sample='<h2>Start with the decision</h2><p>Explain what the reader is trying to decide, then show the costs, limits, and questions that matter.</p><h2>What to check</h2><ul><li>Use current primary sources.</li><li>Show trade-offs and uncertainties.</li><li>Provide a practical next step.</li></ul>'
    return f'''<div class="editor-status"><div><span class="status status-blue">Draft</span><span id="draft-state">Browser-local draft preview · no CMS connected</span></div><div>{button('Preview','secondary','preview')} {button('Save to this browser','primary','save')} {button('Publish ▾','dark','publish')}</div></div>
      <div class="editing-layout"><div class="editing-main"><div class="studio-panel story-setup"><span class="admin-kicker">THE STORY</span><label class="admin-field"><span>Headline <em>*</em></span><input class="headline-input" id="editor-title" value="A clearer way to build an emergency fund" aria-label="Article headline"></label><label class="admin-field"><span>Short description</span><textarea id="editor-summary" rows="2">A practical framework for choosing a target, setting a pace, and keeping cash available when you need it.</textarea><small>A concise summary for listings and search results.</small></label></div>
      <section class="studio-panel editor-panel"><div class="editor-panel-top"><span class="admin-kicker">ARTICLE BODY</span><span id="editor-mode">TinyMCE setup</span></div><div class="tinymce-setup" id="tinymce-setup"><div><strong>Write with TinyMCE</strong><p>Enter your Tiny Cloud API key to activate the visual editor. The key is kept in this browser for this preview. Add this Site’s domain to your approved domains in Tiny Cloud.</p></div><label class="sr-only" for="tinymce-key">Tiny Cloud API key</label><div class="tinymce-key-row"><input id="tinymce-key" type="password" autocomplete="off" placeholder="Your Tiny Cloud API key"><button class="a-button primary" id="activate-tinymce" type="button">Activate editor</button><button class="a-button secondary" id="forget-tinymce-key" type="button">Forget key</button></div><p id="tinymce-status" role="status">No API key is configured. You can still edit the HTML below.</p></div><label class="sr-only" for="article-body">Article body HTML</label><textarea id="article-body" name="body" aria-label="Article body HTML" data-tinymce-key="" rows="19">{escape(sample)}</textarea><div class="editor-bottom"><span>Use headings, short paragraphs, lists, and links to sources.</span><span id="word-count">0 words</span></div></section>
      <div class="studio-panel seo-preview"><div class="panel-head"><div><span class="admin-kicker">DISCOVERY</span><h2>Search preview</h2></div></div><span class="search-domain">financershub.com › personal-finance › emergency-fund</span><h3 id="search-preview-title">A clearer way to build an emergency fund</h3><p>A practical framework for choosing a target, setting a pace, and keeping cash available when you need it.</p></div></div>
      <aside class="editing-side"><div class="studio-panel side-module"><div class="module-head">Publishing <span>⌄</span></div><label class="admin-field"><span>Status</span><select><option>Draft</option><option>In review</option><option>Scheduled</option><option>Published</option></select></label>{field('Publish date','','datetime-local')}<div class="mini-info"><span>Storage</span><strong>This browser only</strong></div></div><div class="studio-panel side-module"><div class="module-head">Classification <span>⌄</span></div><label class="admin-field"><span>Primary category</span><select><option>Personal Finance</option><option>Investing</option><option>Banking</option><option>Credit</option></select></label>{field('Tags','Emergency fund, Saving')}</div><div class="studio-panel side-module"><div class="module-head">Featured media <span>⌄</span></div><img class="editor-media" src="/assets/images/editorial-personal-finance.webp" width="300" height="170" alt="Notebook and pen on a desk">{button('Change image','secondary','media')}<p class="small-muted">Confirm image rights and add meaningful alternative text where needed.</p></div><div class="studio-panel side-module"><div class="module-head">Editorial checks <span>⌄</span></div><label class="check-line"><input type="checkbox"> Primary sources checked</label><label class="check-line"><input type="checkbox"> Copy and image rights reviewed</label><label class="check-line"><input type="checkbox"> Disclaimer reviewed</label><label class="check-line"><input type="checkbox"> Second editorial review</label></div></aside></div>'''

