def taxonomy(section, categories):
    if section=='categories':
        records=[(c,f'{c.lower().replace(" ","-")}',[18,14,12,10,9,8,7,6,5,4,3][i]) for i,c in enumerate(categories)]
        rows=''.join(f'<tr><td><strong>{n}</strong><small>Guides and explainers about {n.lower()}.</small></td><td class="mono">/{slug}</td><td>{count} articles</td><td>{badge("Visible","green")}</td><td>{button("Edit", "text", "edit")}</td></tr>' for n,slug,count in records)
        return f'''<div class="admin-two-col taxonomy-layout"><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">SITE STRUCTURE</span><h2>Categories</h2></div>{button('＋ New category','primary','new-category')}</div><div class="table-scroll"><table class="studio-table"><thead><tr><th>Name</th><th>URL slug</th><th>Content</th><th>State</th><th></th></tr></thead><tbody>{rows}</tbody></table></div></section><aside class="studio-panel taxonomy-guide"><span class="admin-kicker">ORGANIZATION</span><h2>A useful path through the library.</h2><p>Categories shape main navigation and article breadcrumbs. Keep names distinct and reader-focused.</p><div class="guide-sample"><span>Example hierarchy</span><strong>Home <i>›</i> Investing <i>›</i> Article</strong></div></aside></div>'''
    tags=['Beginner guide','Explainer','Comparison','How-to','Credit basics','Risk','Cash flow','Financial planning','Review']
    return f'''<div class="admin-two-col taxonomy-layout"><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">TOPIC CONNECTIONS</span><h2>Tags</h2></div>{button('＋ New tag','primary','new-tag')}</div><div class="tag-rows">{''.join(f'<div><span class="admin-tag">{t}</span><span>{(i*3+4)} articles</span>{button("Edit", "text", "edit")}</div>' for i,t in enumerate(tags))}</div></section><aside class="studio-panel taxonomy-guide"><span class="admin-kicker">EDITORIAL RULE</span><h2>Use tags with restraint.</h2><p>Tags should help readers find a meaningful connection. A category remains the main home for each article.</p></aside></div>'''

def authors():
    return '''<div class="list-toolbar"><span class="small-muted">Profiles shown here are placeholders for design review.</span><button class="a-button primary" type="button" data-admin-action="invite">＋ Add contributor</button></div><div class="author-grid"><article class="studio-panel author-card"><div class="author-avatar">FH</div><span class="status status-blue">Editorial team</span><h2>FinancersHub editorial team</h2><p>Shared sample attribution for the design preview. Replace with verified people and roles before launch.</p><div><span>Articles <strong>11</strong></span><span>Profile <strong>Needs verification</strong></span></div><button class="a-button secondary" type="button" data-admin-action="edit">Edit profile</button></article><article class="studio-panel author-invite"><span>＋</span><h2>Bring in a contributor</h2><p>Every writer profile should show a verified name, relevant experience, and a clear editorial role.</p><button class="a-button secondary" type="button" data-admin-action="invite">Create author profile</button></article></div>'''

def comments():
    notes=[('Jordan M.','This explanation helped me understand how to set my first milestone.','Emergency fund guide','Pending'),('A reader','Could you explain how this changes with variable income?','Saving and investing','Pending'),('Alex R.','The comparison table was especially useful.','Bank account guide','Approved')]
    return '<div class="list-toolbar"><div class="segmented"><button class="selected" data-comment-filter="all">All</button><button data-comment-filter="pending">Pending</button><button data-comment-filter="approved">Approved</button></div><span class="small-muted">Moderation actions are preview-only</span></div><div class="comment-layout"><section class="comment-list">'+''.join(f'<article class="studio-panel comment-card" data-comment-status="{status.lower()}"><div class="comment-top"><span class="comment-avatar">{name[0]}</span><div><strong>{name}</strong><small>On “{story}” · sample comment</small></div>{badge(status,"amber" if status=="Pending" else "green")}</div><p>{copy}</p><div class="comment-actions">{button("Approve","secondary","approve")} {button("Reply","secondary","reply")} {button("More ⋯","text","more")}</div></article>' for name,copy,story,status in notes)+'</section><aside class="studio-panel taxonomy-guide"><span class="admin-kicker">MODERATION PRINCIPLES</span><h2>Keep discussion useful.</h2><p>Review questions for relevance and civility. Do not treat reader comments as verified financial guidance.</p></aside></div>'

def seo():
    return f'''<div class="seo-layout"><div><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">DEFAULTS</span><h2>Search appearance</h2></div>{badge('Preview','blue')}</div><div class="field-grid">{field('Site title','FinancersHub')}{field('Title suffix','| FinancersHub')}</div><label class="admin-field"><span>Default description</span><textarea rows="3">Clear explanations for real financial decisions.</textarea><small>Individual article metadata should override this description.</small></label></section><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">SHARING</span><h2>Social preview</h2></div></div><div class="social-preview"><div class="social-cover"><img src="/assets/logo-white.svg" alt="FinancersHub" width="190" height="35"><span>FINANCE, EXPLAINED</span></div><div><strong>FinancersHub · Clear thinking about money</strong><span>financershub.com</span></div></div><p class="small-muted">The final social template needs article-specific titles and accessible text-safe crops.</p></section></div><aside class="studio-panel seo-checklist"><span class="admin-kicker">PUBLICATION CHECKLIST</span><h2>Search readiness</h2><div><span>✓</span><strong>Readable article structure</strong><small>One title and a logical heading order</small></div><div><span>✓</span><strong>Author attribution</strong><small>Visible near the article title</small></div><div><span>○</span><strong>Verified canonical URLs</strong><small>Connect when publishing routes exist</small></div><div><span>○</span><strong>Structured article data</strong><small>Add from verified content records</small></div>{button('Review settings','secondary','save')}</aside></div>'''

def advertisements():
    slots=[('Homepage leaderboard','Across content sections','Responsive · 970 × 90','Reserved'),('Article top','After article introduction','Responsive · 728 × 90','Reserved'),('Article middle','Within long-form content','Responsive · 728 × 90','Reserved'),('Article sidebar','Beside contextual reading','300 × 250','Reserved'),('Mobile in-feed','Between story groups','320 × 100','Reserved')]
    cards=''.join(f'<article class="slot-card"><div class="slot-preview"><span>ADVERTISEMENT</span><small>{size}</small></div><div class="slot-details"><span>{badge(state,"blue")}</span><h3>{name}</h3><p>{where}</p>{button("Placement details", "text", "slot")}</div></article>' for name,where,size,state in slots)
    return f'''<div class="admin-two-col ads-layout"><section><div class="list-toolbar"><p class="small-muted">Slots reserve space to protect the reading experience.</p>{button('＋ New placement','primary','new-slot')}</div><div class="slot-grid">{cards}</div></section><aside class="studio-panel ad-guidelines"><span class="admin-kicker">AD PRINCIPLES</span><h2>Revenue without disruption.</h2><p>All ad placements are visibly labeled and have predictable dimensions. This screen is an inventory; no ad network is connected.</p><ul><li>Reserve the expected slot height</li><li>Keep ads separate from editorial cards</li><li>Use fewer slots on narrow screens</li></ul></aside></div>'''

def faq():
    rows=''.join(f'<article class="faq-edit-item"><label class="admin-field"><span>Question</span><input class="faq-question" value="{escape(q,quote=True)}" required></label><label class="admin-field"><span>Answer</span><textarea class="faq-answer-edit" rows="4" required>{escape(answer)}</textarea></label><button type="button" class="a-button secondary faq-remove">Remove question</button></article>' for _,group in FAQ_GROUPS for q,answer in group)
    return f'''<div class="admin-two-col faq-admin-layout"><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">READER HELP</span><h2>Frequently asked questions</h2></div><a href="/faq.html" target="_blank" rel="noopener">View current page ↗</a></div><p class="small-muted">Edit a draft of the FAQ text here. Saving keeps it in this browser; changes will appear on the public page after a CMS is connected and published.</p><form id="faq-admin-form"><div id="faq-edit-list">{rows}</div><div class="faq-admin-actions"><button type="button" id="faq-add" class="a-button secondary">＋ Add question</button><button type="submit" class="a-button primary">Save draft in this browser</button></div><p id="faq-admin-status" role="status"></p></form></section><aside class="studio-panel taxonomy-guide"><span class="admin-kicker">WRITING NOTES</span><h2>Give readers a direct answer.</h2><p>Use one question per topic, plain language, and links to the full policy or guide when readers need detail.</p><p>Do not promise newsletter delivery or personalized advice before those services are available.</p></aside></div>'''

def newsletter():
    return '''<div class="admin-metrics three"><div><span>Subscribers</span><strong>—</strong><small>No signup service connected</small><i>✉</i></div><div><span>Campaigns</span><strong>—</strong><small>Delivery not connected</small><i>✎</i></div><div><span>Signup placement</span><strong>01</strong><small>Above the footer</small><i>▧</i></div></div><div class="newsletter-workflow"><section class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">SIGNUP COPY</span><h2>Newsletter invitation</h2></div><a href="/#newsletter" target="_blank" rel="noopener">View current placement ↗</a></div><p class="small-muted">Draft copy for the pre-footer signup. Save it in this browser for review; connect an email provider and publishing backend before collecting addresses.</p><form id="newsletter-admin-form"><label class="admin-field"><span>Title</span><input id="newsletter-title-edit" value="Good questions for better money decisions."></label><label class="admin-field"><span>Description</span><textarea id="newsletter-description-edit" rows="3">A short selection of practical guides, delivered when the newsletter launches.</textarea></label><label class="admin-field"><span>Button label</span><input id="newsletter-button-edit" value="Get updates"></label><div class="setting-actions"><button class="a-button primary" type="submit">Save draft in this browser</button></div><p id="newsletter-admin-status" role="status"></p></form></section><aside class="studio-panel signup-preview"><span class="admin-kicker">READER EXPERIENCE</span><h2>One useful idea at a time.</h2><p>State what readers will receive, how often, and how to unsubscribe when email delivery is ready.</p><div class="signup-mock"><span>Email address</span><strong>Get updates ↗</strong></div><small>The public form is a preview and does not collect addresses.</small><a href="/faq.html#newsletter-and-contact">Read the newsletter FAQ ↗</a></aside></div>'''

def settings():
    return f'''<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections"><a href="#identity" class="selected">Site identity</a><a href="#navigation">Navigation</a><a href="#appearance">Appearance</a><a href="#integrations">Integrations</a></nav><div><section id="identity" class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">PUBLICATION</span><h2>Site identity</h2></div></div><div class="field-grid">{field('Publication name','FinancersHub')}{field('Public site URL','financershub.com')}</div><label class="admin-field"><span>Short description</span><textarea rows="3">Clear explanations for real financial decisions.</textarea></label><div class="setting-actions">{button('Save changes','primary','save')}</div></section><section id="navigation" class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">WAYFINDING</span><h2>Main navigation</h2></div></div><div class="nav-order">{''.join(f'<div><span>⠿</span><strong>{item}</strong><span>Visible</span></div>' for item in ['Personal Finance','Investing','Banking','Credit','Business','Saving'])}</div></section><section id="appearance" class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">BRAND</span><h2>Appearance</h2></div></div><div class="brand-swatches"><span style="background:#132c43"></span><span style="background:#137b71"></span><span style="background:#edf3f1"></span><strong>Navy / teal editorial system</strong></div></section><section id="integrations" class="studio-panel"><div class="panel-head"><div><span class="admin-kicker">FUTURE CONNECTIONS</span><h2>Integrations</h2></div></div><p class="small-muted">Advertising, newsletter delivery, analytics, and content storage will be connected in a later phase.</p></section></div></div>'''

def render_admin(section, articles, categories):
    pages={'index':lambda:overview(articles),'articles':lambda:article_list(articles),'editor':editor,'media':media,'categories':lambda:taxonomy('categories',categories),'tags':lambda:taxonomy('tags',categories),'authors':authors,'comments':comments,'faq':faq,'seo':seo,'advertisements':advertisements,'newsletter':newsletter,'settings':settings}
    return shell(section,pages[section]())
